package com.zeronet.mobile.model

/** Which leg of the path a route change belongs to. */
enum class RouteLeg { A, B }

/**
 * One route change, as the user sees it in history.
 *
 * Leg-B events come from the admin backend (`GET /api/v1/events?kind=route`,
 * generated by the Rust pair engine); leg-A events are generated in Kotlin by
 * the client-side race/health logic and merged locally, newest first.
 */
data class RouteEvent(
    val at: Long,
    val leg: RouteLeg,
    val from: String,
    val to: String,
    val reason: String,
    val metrics: Map<String, Double> = emptyMap(),
) {
    fun toJson(): org.json.JSONObject = org.json.JSONObject()
        .put("at", at)
        .put("leg", leg.name)
        .put("from", from)
        .put("to", to)
        .put("reason", reason)
        .put("metrics", org.json.JSONObject(metrics))

    companion object {
        fun fromJson(o: org.json.JSONObject): RouteEvent = RouteEvent(
            at = o.optLong("at"),
            leg = if (o.optString("leg").equals("B", ignoreCase = true)) RouteLeg.B else RouteLeg.A,
            from = o.optString("from"),
            to = o.optString("to"),
            reason = o.optString("reason"),
            metrics = o.optJSONObject("metrics")?.let { m ->
                m.keys().asSequence().associateWith { m.optDouble(it) }
            } ?: emptyMap(),
        )
    }
}
